<script>(function(){function f(n){return n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',')}
var ups=document.querySelectorAll('.up'),del=document.getElementById('del');function calc(){var s=0;ups.forEach(function(u){var tr=u.closest('tr'),av=tr.querySelector('.av').checked,v=parseFloat(u.value),a=av&&!isNaN(v)?Math.round(v*parseFloat(u.getAttribute('data-q'))*100)/100:null;tr.querySelector('.am').textContent=a===null?'-':f(a);if(a!==null)s+=a;u.disabled=false;tr.style.opacity=av?'1':'.5'});s=Math.round(s*100)/100;document.getElementById('sub').textContent=f(s);var d=parseFloat(del.value);document.getElementById('tot').textContent=f(s+(isNaN(d)?0:d))}
if(ups.length&&del){document.addEventListener('input',calc);document.addEventListener('change',calc);calc()}
var mv=document.getElementById('mv');if(mv){function sh(){document.querySelectorAll('[class*="mv-"]').forEach(function(e){e.style.display=e.classList.contains('mv-'+mv.value)?'':'none'})}mv.onchange=sh;sh()}})();</script>
